Your problem is that live isn't bound to any specific set of elements, it is bound to whatever elements match a particular selector at the time the click event happens. That means that you can't use unbind or off to stop the click from triggering the handler. You can, however, slightly modify your selector to exclude elements with a certain class and then add that class to tell live to ignore your element:

$('.el a:not(.been-clicked)').live('click', function(event){
  event.preventDefault();

  var $this = $(this);
  $.ajax({
    url: $this.attr('href'),
    type: 'GET',      
    success: function(response){
      $this.addClass('been-clicked');
    }
  });
});

